import{_ as s,o,c as e,af as a}from"./chunks/framework._zKnALF5.js";const p=JSON.parse('{"title":"部署说明","description":"","frontmatter":{},"headers":[],"relativePath":"ops/deployment.md","filePath":"ops/deployment.md","lastUpdated":null}'),i={name:"ops/deployment.md"};function n(d,t,r,l,c,g){return o(),e("div",null,[...t[0]||(t[0]=[a(`<h1 id="部署说明" tabindex="-1">部署说明 <a class="header-anchor" href="#部署说明" aria-label="Permalink to &quot;部署说明&quot;">​</a></h1><h2 id="生产构建" tabindex="-1">生产构建 <a class="header-anchor" href="#生产构建" aria-label="Permalink to &quot;生产构建&quot;">​</a></h2><p><strong>（服务端代码）</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/index.js</span></span></code></pre></div><h2 id="基础部署建议" tabindex="-1">基础部署建议 <a class="header-anchor" href="#基础部署建议" aria-label="Permalink to &quot;基础部署建议&quot;">​</a></h2><ul><li>使用 <code>pm2</code> 或容器编排管理进程</li><li>配置反向代理（Nginx）与 HTTPS</li><li>将敏感配置放入环境变量，不提交到仓库</li></ul><h2 id="健康检查与日志" tabindex="-1">健康检查与日志 <a class="header-anchor" href="#健康检查与日志" aria-label="Permalink to &quot;健康检查与日志&quot;">​</a></h2><ul><li>提供健康检查接口用于探针监控</li><li>记录关键日志：登录、房间加入、异常栈</li><li>统一日志采集，便于排障与审计</li></ul><h2 id="多实例注意事项" tabindex="-1">多实例注意事项 <a class="header-anchor" href="#多实例注意事项" aria-label="Permalink to &quot;多实例注意事项&quot;">​</a></h2><ul><li>Redis 用于共享状态与 Pub/Sub 同步（世界聊天）</li><li>所有实例需保持一致的 JWT 签名配置</li><li>建议配置连接数上限，避免单实例过载</li></ul><h2 id="人数压力测" tabindex="-1">人数压力测 <a class="header-anchor" href="#人数压力测" aria-label="Permalink to &quot;人数压力测&quot;">​</a></h2><p>上线前或扩容前，可使用专用 <strong><code>loadtest_room</code></strong> 与 <code>loadtest/concurrent-join.ts</code> 做并发连接与消息打点；生产务必关闭压测房或限制访问。详见 <a href="/ops/load-testing.html">人数压力测</a>。</p><h2 id="文档站静态资源-vitepress" tabindex="-1">文档站静态资源（VitePress） <a class="header-anchor" href="#文档站静态资源-vitepress" aria-label="Permalink to &quot;文档站静态资源（VitePress）&quot;">​</a></h2><ul><li>默认 <code>base</code> 为 <code>/</code>，打包后 HTML 会引用以 <code>/</code> 开头的资源（如 <code>/assets/...</code>），适合站点挂在<strong>域名根路径</strong>（含 <strong>GitHub Pages + 自定义域名</strong>，见下）。</li><li><strong>GitHub Pages 自定义域名</strong>：在仓库 Settings → Pages 绑定域名后，对外访问一般为 <strong><code>https://你的域名/</code></strong>（内容在根路径，<strong>没有</strong> <code>/仓库名/</code> 前缀）。此时必须把 VitePress 的 <code>base</code> 设为 <strong><code>&#39;/&#39;</code></strong>，否则 HTML 仍会请求 <code>/仓库名/assets/...</code>，在自定义域名下会 <strong>404</strong>。</li><li><strong>GitHub Pages 默认子路径</strong>（未用自定义域名、仅用 <code>https://&lt;用户&gt;.github.io/&lt;仓库名&gt;/</code>）时，必须把 <code>base</code> 设为 <strong><code>/&#39;&lt;仓库名&gt;/&#39;</code></strong>（首尾都要有 <code>/</code>）。若 <code>base</code> 仍为 <code>/</code>，会出现首页闪一下后变为站内 <strong>404</strong>（路由按域名根解析，与实际子路径不一致）。</li><li>不要用 <code>base: &#39;./&#39;</code> 代替子路径：多级目录页面上的 <code>./assets/...</code> 容易解析到错误目录。</li><li>构建产物目录：<code>docs/.vitepress/dist</code>，可用 <code>npm run docs:build</code> / <code>npm run docs:preview</code>。</li><li><strong>本地 <code>docs:dev</code></strong>：<code>base</code> 为 <code>/</code> 时从 <strong><code>http://localhost:端口/</code></strong> 打开即可。若曾使用非根 <code>base</code>（如 <code>/仓库名/</code>），须从 <strong><code>http://localhost:端口/仓库名/</code></strong> 打开，否则静态资源与 <strong>favicon</strong> 会请求到错误路径。</li></ul><h2 id="文档站-seo-百度、搜狗等" tabindex="-1">文档站 SEO（百度、搜狗等） <a class="header-anchor" href="#文档站-seo-百度、搜狗等" aria-label="Permalink to &quot;文档站 SEO（百度、搜狗等）&quot;">​</a></h2><h3 id="构建产物" tabindex="-1">构建产物 <a class="header-anchor" href="#构建产物" aria-label="Permalink to &quot;构建产物&quot;">​</a></h3><ul><li><strong><code>docs/public/robots.txt</code></strong> → 部署后应在 <strong><code>https://xcs.pyzgame.cn/robots.txt</code></strong> 可访问（<strong>404 说明未部署最新 dist 或 public 未拷贝</strong>）。</li><li><strong><code>npm run docs:build</code></strong> 会在 <code>docs/.vitepress/dist/</code> 生成： <ul><li><strong><code>sitemap.xml</code></strong>（提交百度 sitemap）</li><li><strong><code>baidu-urls.txt</code></strong>（每行一条 URL，可粘贴到站长平台「手动提交」）</li></ul></li><li>全局 <strong>keywords / description / canonical</strong> 见 <strong><code>docs/.vitepress/seo.ts</code></strong>、<strong><code>config.ts</code> 的 <code>transformHead</code></strong>。</li></ul><h3 id="百度「索引量-0」常见原因-不是代码坏了" tabindex="-1">百度「索引量 = 0」常见原因（不是代码坏了） <a class="header-anchor" href="#百度「索引量-0」常见原因-不是代码坏了" aria-label="Permalink to &quot;百度「索引量 = 0」常见原因（不是代码坏了）&quot;">​</a></h3><p><strong>验证通过 ≠ 已收录。</strong> 站长平台显示「已验证」只表示你拥有站点；<strong>索引量</strong>要等百度抓取并入库，新站常见 <strong>数天～数周</strong> 仍为 0。</p><table tabindex="0"><thead><tr><th>检查项</th><th>说明</th></tr></thead><tbody><tr><td>是否<strong>重新部署</strong></td><td><code>robots.txt</code>、<code>sitemap.xml</code>、验证 TXT 都在 <strong>dist 根目录</strong>；只改本地不 push / 不跑 Actions 则线上没有。</td></tr><tr><td>是否<strong>提交 sitemap</strong></td><td><a href="https://ziyuan.baidu.com/" target="_blank" rel="noreferrer">百度搜索资源平台</a> → 资源提交 → <strong>sitemap</strong> → 填 <code>https://xcs.pyzgame.cn/sitemap.xml</code>。</td></tr><tr><td>是否<strong>主动推送 URL</strong></td><td>普通收录 → <strong>API 推送</strong> 或 <strong>手动提交</strong>（见下）；只放 sitemap 往往较慢。</td></tr><tr><td>站点是否<strong>可被公网访问</strong></td><td>用手机 4G（非公司 VPN）打开首页；<code>hosts</code> 把域名指到 <code>127.0.0.1</code> 时百度抓不到真实服务器。</td></tr><tr><td>是否<strong>新站</strong></td><td>技术文档站外链少，百度发现慢，需主动推送 + 等待。</td></tr></tbody></table><h3 id="推荐操作顺序-自定义域名-xcs-pyzgame-cn" tabindex="-1">推荐操作顺序（自定义域名 <code>xcs.pyzgame.cn</code>） <a class="header-anchor" href="#推荐操作顺序-自定义域名-xcs-pyzgame-cn" aria-label="Permalink to &quot;推荐操作顺序（自定义域名 \`xcs.pyzgame.cn\`）&quot;">​</a></h3><ol><li><strong>部署最新文档</strong>（push 到触发 GitHub Pages 的分支，等 Actions 绿）。</li><li>浏览器自检（必须 <strong>200</strong>）： <ul><li><code>https://xcs.pyzgame.cn/robots.txt</code></li><li><code>https://xcs.pyzgame.cn/sitemap.xml</code></li><li><code>https://xcs.pyzgame.cn/25c5429258715746c19faf393677c071.txt</code>（若仍用 TXT 验证）</li></ul></li><li>站长平台 → <strong>普通收录</strong> → <strong>API 推送</strong>：复制接口里的 <strong><code>token</code></strong>，在本地执行（勿把 token 提交 git）：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># PowerShell</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$env:BAIDU_PUSH_SITE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xcs.pyzgame.cn&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$env:BAIDU_PUSH_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你的token&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:push-baidu</span></span></code></pre></div><p>或把 <strong><code>docs/.vitepress/dist/baidu-urls.txt</code></strong> 内容粘贴到「<strong>手动提交</strong>」。</p><ol start="4"><li><strong>sitemap 提交</strong>：<code>https://xcs.pyzgame.cn/sitemap.xml</code></li><li><strong>抓取诊断</strong>（站长平台）：输入首页 URL，看「抓取是否成功」「HTTP 状态码」。</li><li><strong>等待 3～14 天</strong> 再看索引量；期间可在「链接提交」里每周补推重要页面。</li></ol><h3 id="搜狗收录" tabindex="-1">搜狗收录 <a class="header-anchor" href="#搜狗收录" aria-label="Permalink to &quot;搜狗收录&quot;">​</a></h3><ul><li>站长验证 meta 通过 <strong><code>transformHtml</code> 紧挨在 <code>&lt;head&gt;</code> 之后</strong> 注入（避免落在 <code>&lt;script&gt;</code> 后面导致搜狗报「抓取验证的内容不一致」）。验证码见 <strong><code>seo.ts</code></strong> 的 <strong><code>SOGOU_SITE_VERIFICATION</code></strong> / <strong><code>BAIDU_SITE_VERIFICATION</code></strong>。</li><li>站点为 <strong>UTF-8</strong>，无需再加 <code>Content-Type: gb2312</code>（该写法易与 VitePress 默认 <code>charset=utf-8</code> 冲突）。</li><li>部署后在 <a href="https://zhanzhang.sogou.com/" target="_blank" rel="noreferrer">搜狗站长平台</a> 添加站点 → <strong>HTML 标签验证</strong> → 用手机 4G 打开 <code>https://xcs.pyzgame.cn/</code> → 查看网页源代码，确认 <code>&lt;head&gt;</code> 开头几行即有 <code>sogou_site_verification</code> → 再点「完成验证」。</li><li>若仍失败：检查站长平台填写的域名是否与访问一致（<code>xcs.pyzgame.cn</code>，不要混用 <code>www</code>）；删除站点重新添加可刷新验证码。</li><li><strong>Sitemap 提交</strong>：<code>https://xcs.pyzgame.cn/sitemap.xml</code>（与百度共用同一份 <code>sitemap.xml</code>）。</li><li><code>robots.txt</code> 已允许 <strong>Sogou web spider</strong> / <strong>Sogou inst spider</strong> 抓取。</li></ul><h3 id="修改域名时" tabindex="-1">修改域名时 <a class="header-anchor" href="#修改域名时" aria-label="Permalink to &quot;修改域名时&quot;">​</a></h3><p>同步改 <strong><code>seo.ts</code> 的 <code>SITE_URL</code></strong>、<code>robots.txt</code> 的 Sitemap、百度/搜狗站长平台里绑定的站点，并重新 build + 部署 + 推送。</p>`,29)])])}const u=s(i,[["render",n]]);export{p as __pageData,u as default};
